from machine import Pin
import time
from nec_ir import NEC

ir = NEC(Pin({OUT}, Pin.IN))
print('listening')
while True:
    r = ir.read()
    if r:
        addr, cmd = r
        if cmd == NEC.REPEAT:
            print('repeat')
        elif cmd == NEC.ERROR:
            print('bad frame')
        else:
            print('addr %02x cmd %02x' % (addr, cmd))
    time.sleep_ms(10)
